// Urspruengliche Nachricht und Session-ID aus dem Enricher-Chat holen
const enricherInput = $('FPCEnricherChat').first().json;
const originalRequest = enricherInput.chatInput || '';
const sessionId = enricherInput.sessionId || ('enricher-' + Date.now());

// Aufbereitete Spezifikation aus der LLM Chain
const enrichedSpec = $input.first().json.text || '';

// Anreicherungs-Header + Spezifikation zusammenbauen
const forwardMessage = `[AUFBEREITETE ANFRAGE vom FPCRequestEnricher]

${enrichedSpec}

---
[Bitte verwende die obige strukturierte Spezifikation als Grundlage. Suche ZUERST in der Knowledge Base nach passenden Mustern mit den angegebenen Suchbegriffen, bevor du Code generierst.]`;

return [{
  json: {
    action: 'sendMessage',
    sessionId: sessionId,
    chatInput: forwardMessage,
    _meta: {
      originalRequest: originalRequest,
      sessionId: sessionId
    }
  }
}];

// Antwort vom FPCSelfLearning extrahieren und weiterleiten
const response = $input.first().json;

// n8n Chat-Trigger antwortet mit { output: '...' }
const agentOutput = response.output
  || response.text
  || response.message
  || response.response
  || JSON.stringify(response, null, 2);

return [{
  json: {
    output: agentOutput
  }
}];
